begin;
select no_plan();

insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select ('90000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','production-test-'||r||'@example.test','',now(),'{}','{}',now(),now()
from (values(1,'administrator'),(2,'editor'),(3,'writer'),(4,'analyst'),(5,'data_editor')) roles(n,r);
update public.profiles set role=case right(id::text,1) when '1' then 'administrator'::public.user_role when '2' then 'editor'::public.user_role when '3' then 'writer'::public.user_role when '4' then 'analyst'::public.user_role else 'data_editor'::public.user_role end where id::text like '90000000-%';
-- Isolate queue claims within this rollback-only test transaction.
update public.pipeline_jobs set status='cancelled' where status in ('queued','running');
select set_config('atlas.revision','on',true);
update public.chart_snapshots set status='replaced' where status='approved' and snapshot_date=(now() at time zone 'Asia/Ulaanbaatar')::date;
select set_config('atlas.revision','off',true);
update public.pipeline_jobs set idempotency_key=idempotency_key||':pgtap-hidden' where idempotency_key='apple_music:mn:'||(now() at time zone 'Asia/Ulaanbaatar')::date;
update public.collection_jobs set idempotency_key=idempotency_key||':pgtap-hidden' where idempotency_key='apple_music:mn:'||(now() at time zone 'Asia/Ulaanbaatar')::date;
create temporary table fixture (entries jsonb,job uuid,token uuid,attempt uuid,snapshot uuid,story uuid,preview jsonb,operation uuid);
insert into fixture(entries) select jsonb_agg(jsonb_build_object('rank',n,'itemId','production-fixture-'||n,'title','Production fixture '||n,'artistName','Production Artist','artistId','production-artist','url','https://music.apple.com/mn/song/'||n) order by n) from generate_series(1,100) n;
update fixture set job=public.enqueue_collection((now() at time zone 'Asia/Ulaanbaatar')::date);
select is(public.enqueue_collection((now() at time zone 'Asia/Ulaanbaatar')::date),(select job from fixture),'enqueue is idempotent');
update fixture set token=(select lease_token from public.claim_pipeline_job());
select is((select count(*)::integer from public.claim_pipeline_job()),0,'an active lease cannot be claimed twice');
with a as (insert into public.collection_attempts(job_id,attempt_number,lease_token,source_url,http_status,raw_body,checksum) select job,1,token,'https://example.com/fixture',200,'{}',repeat('f',64) from fixture returning id) update fixture set attempt=(select id from a);
select throws_ok($$update public.collection_attempts set raw_body='changed' where id=(select attempt from fixture)$$,'collection_attempts is append-only','failed and successful source evidence cannot be edited');
update public.pipeline_jobs set lease_until=now()-interval '1 second' where id=(select job from fixture);
select throws_ok($$select public.finish_pipeline_failure((select job from fixture),(select token from fixture),'expired','expired worker')$$,'lost job lease','expired worker cannot publish a late failure');
update public.pipeline_jobs set lease_until=now()+interval '90 seconds' where id=(select job from fixture);
select throws_ok($$select public.complete_collection((select job from fixture),gen_random_uuid(),(select attempt from fixture),'{}',(select entries from fixture))$$,'lost job lease','a stale worker cannot complete ingestion');
select throws_ok($$select public.complete_collection((select job from fixture),(select token from fixture),(select attempt from fixture),'{}','[]')$$,'expected 100 entries, received 0','invalid ingestion fails safely');
select is((select count(*)::integer from public.collection_attempts where id=(select attempt from fixture)),1,'raw evidence survives failed validation');
update fixture set snapshot=public.complete_collection(job,token,attempt,'{}',entries);
select is((select status from public.pipeline_jobs where id=(select job from fixture)),'succeeded','lease holder completes collection');
select is((select count(*)::integer from public.pipeline_jobs where snapshot_id=(select snapshot from fixture) and kind='calculate'),1,'calculation work is committed with the snapshot');
select throws_ok($$update public.chart_snapshots set checksum='changed' where id=(select snapshot from fixture)$$,'approved snapshot headers are immutable','approved source headers cannot change');
select throws_ok($$insert into public.chart_entries(snapshot_id,platform_asset_id,song_id,rank,entry_status,peak_rank,days_on_chart) select snapshot_id,platform_asset_id,song_id,101,'new',101,1 from public.chart_entries where snapshot_id=(select snapshot from fixture) limit 1$$,'entries belonging to an approved snapshot are immutable','rows cannot be appended to an approved snapshot');
select throws_ok($$update public.chart_entries set rank=200 where snapshot_id=(select snapshot from fixture)$$,'entries belonging to an approved snapshot are immutable','source ranks cannot be edited');
select throws_ok($$select public.finish_pipeline_failure((select job from fixture),(select token from fixture),'late','late failure')$$,'lost job lease','late failure cannot overwrite a successful job');
select ok(not has_table_privilege('anon','public.collection_attempts','SELECT'),'raw attempts are private');
select ok(not has_table_privilege('anon','public.editorial_drafts','SELECT'),'unpublished drafts are private');
select ok(not has_function_privilege('authenticated','public.complete_collection(uuid,uuid,uuid,jsonb,jsonb)','EXECUTE'),'staff cannot invoke service ingestion');

with s as (insert into public.story_leads(headline,angle,supporting_facts) values('Баталгаажуулах нийтлэл','Fixture evidence','[{"source":"fixture"}]') returning id) update fixture set story=(select id from s);
grant select,update on fixture to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000004',true);
select throws_ok($$select public.save_story((select story from fixture),1,'verify')$$,'forbidden','analyst cannot verify a story');
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.save_story((select story from fixture),1,'publish')$$,'approval required','publication requires explicit draft approval');
select is(public.save_story((select story from fixture),1,'verify'),2,'editor verifies a lead');
select is(public.save_story((select story from fixture),2,'assign','{"assignee":"90000000-0000-4000-8000-000000000003"}'),3,'editor assigns an active writer');
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000003',true);
select throws_ok($$select public.save_story((select story from fixture),2,'draft','{"headlineMn":"Гарчиг","bodyMn":"Нийтлэл"}')$$,'conflict: reload the latest revision','stale editor tabs cannot overwrite current work');
select is(public.save_story((select story from fixture),3,'draft','{"headlineMn":"Гарчиг","bodyMn":"Нотолгоотой нийтлэл"}'),4,'assigned writer saves an immutable draft');
select is(public.save_story((select story from fixture),4,'submit'),5,'writer submits for editing');
select throws_ok($$select public.save_story((select story from fixture),5,'approve')$$,'forbidden','writer cannot approve their own draft');
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000002',true);
select is(public.save_story((select story from fixture),5,'approve'),6,'editor approves the exact draft revision');
select is(public.save_story((select story from fixture),6,'publish','{"channel":"atlas"}'),7,'editor publishes the approved Mongolian article');
set local role anon;
select is((select count(*)::integer from public.publications where headline_mn='Гарчиг'),1,'public readers see a published article');
reset role;
select throws_ok($$update public.editorial_drafts set body_mn='changed' where story_id=(select story from fixture)$$,'editorial_drafts is append-only','draft history is immutable');
select throws_ok($$delete from public.publications where story_id=(select story from fixture)$$,'publications is append-only','publication records are immutable');

set local role authenticated;
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000001',true);
update fixture set preview=public.catalog_operation('merge',(select song_id from public.chart_entries where snapshot_id=(select snapshot from fixture) and rank=1),(select song_id from public.chart_entries where snapshot_id=(select snapshot from fixture) and rank=2),'{}','Preview',true);
select ok((select preview->>'fingerprint' is not null from fixture),'merge preview supplies a concurrency fingerprint');
select is((select count(*)::integer from public.catalog_operations where source_id=(select song_id from public.chart_entries where snapshot_id=(select snapshot from fixture) and rank=1)),0,'preview does not mutate catalog history');
select throws_ok($$select public.catalog_operation('merge',(select song_id from public.chart_entries where snapshot_id=(select snapshot from fixture) and rank=1),(select song_id from public.chart_entries where snapshot_id=(select snapshot from fixture) and rank=2),'{}','Verified duplicate recording',false,'stale')$$,'conflict: preview again','merge rejects an outdated impact preview');
update fixture set operation=(public.catalog_operation('merge',(select song_id from public.chart_entries where snapshot_id=(select snapshot from fixture) and rank=1),(select song_id from public.chart_entries where snapshot_id=(select snapshot from fixture) and rank=2),'{}','Verified duplicate recording',false,preview->>'fingerprint')->>'operationId')::uuid;
select ok((select redirect_to is not null from public.songs where id=(select song_id from public.chart_entries where snapshot_id=(select snapshot from fixture) and rank=1)),'merged ID remains addressable through a redirect');
select lives_ok($$select public.undo_catalog_operation((select operation from fixture),'Undo reviewed identity mapping')$$,'administrator can undo an unchanged merge');
select ok((select redirect_to is null from public.songs where id=(select song_id from public.chart_entries where snapshot_id=(select snapshot from fixture) and rank=1)),'undo restores the original canonical ID');
reset role;
update public.profiles set active=false where id='90000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000002',true);
select is((select count(*)::integer from public.collection_attempts),0,'inactive staff cannot inspect private source evidence');
select throws_ok($$select public.save_story((select story from fixture),7,'archive')$$,'forbidden','account deactivation takes effect in the database');
reset role;
select ok((select count(*) from public.audit_logs where actor_user_id::text like '90000000-%')=8,'editorial and catalog actions retain actor audit history');
select * from finish();
rollback;
